-- composition of rule kernels build_side_probe_side x common_aggregate (duckdb), template union
SELECT count(*) FROM (SELECT 1 AS k FROM (SELECT ((COUNT (DISTINCT a1.c5) % 1000)::int - 1) AS c0, a1.c5 AS c1, 'A'::text AS c2, COUNT (*) AS c3 FROM t3 AS a1 GROUP BY a1.c2, a1.c5) AS ka UNION ALL SELECT 2 AS k FROM (SELECT '{"k": -1, "a": [1, 2, 3]}'::jsonb AS c0, 0.5::numeric AS c1, 1::bigint AS c2, 'a'::text AS c3 FROM t3 AS a1 HAVING BOOL_AND ((a1.c5 < ANY (SELECT 'NaN'::text AS c0)))) AS kb) AS u;
